import { Component, OnInit } from '@angular/core';
import { Broker, BrokerService } from './broker.service';

@Component({
  selector: 'app-broker',
  templateUrl: './broker.component.html',
  styleUrls: ['./broker.component.css']
})
export class BrokerComponent implements OnInit {
  kompanija: string = 'Еурохаус АД Скопје';
  broker: Broker | null = null;
  error: string | null = null;

  constructor(private brokerService: BrokerService) { }

  ngOnInit(): void { }

  getBroker(): void {
    this.brokerService.getBroker(this.kompanija).subscribe({
      next: (broker) => {
        this.broker = broker;
        this.error = null;
      },
      error: (err) => {
        this.broker = null;
        this.error = err.error?.message || 'Failed to fetch broker';
      }
    });
  }
}
<h2>Broker Details</h2>
<div class="broker-container">
  <label for="kompanija">Kompanija: </label>
  <input id="kompanija" [(ngModel)]="kompanija" placeholder="Enter Kompanija" />
  <button (click)="getBroker()">Get Broker</button>
</div>
<div *ngIf="broker" class="broker-details">
  <p>ID: {{ broker.id }}</p>
  <p>Kompanija: {{ broker.kompanija }}</p>
  <p>Procent Provizija: {{ broker.procentProvizija }}</p>
</div>
<div *ngIf="error" class="error">
  <p>{{ error }}</p>
</div>
